        [80079876] = 'Рукавицы выносливости Борга',
        [80079985] = 'Душемолот изгнания',
        [82876510] = 'Эта техника ведения боя позволяет серафиму быстро выпускать энергетические разряды как по близким, так и по удаленным противникам.',
        [82876627] = 'Вампиресса призывает инкарнацию бога крови, ищущую жерв для кровавого поцелуя. Настигнутые враги получают поцелуй бога крови, который на короткое время обливает их кровью и тем самым наносит периодические повреждения.',
        [82889286] = 'Серафим обрушивает гнев архангела на противника, наносящий ему сильные повреждения.',
        [82889845] = 'Лесная эльфийка кидает катящееся колючее растение во врага. Растение наносит повреждения каждому пораженному противнику. Если в растение попадет стрела, то оно взорвется и нанесет повреждения врагам вокруг.',
        [82915161] = 'Подвижность увеличивает атаку персонажа в бою, тем самым повышая его шанс попадания оружием по противнику.',
        [82915162] = 'Парирование увеличивает защиту персонажа, тем самым повышая шанс отразить вражеские атаки оружием. Защита дополнительно увеличивается за счет использования щита.',
        [82927365] = 'Повышает шанс попадания ударов по врагам.',
        [82927366] = 'Повышает шанс уклониться от атак врагов. Со щитом шанс дополнительно увеличивается.',
        [82952899] = 'Мощный прыжок, наносящий урон одному противнику и оглушающий всех противников в некотором радиусе. Чем больше врагов оглушено, тем больше урона получит цель прыжка.',
        [82952902] = 'Яростный клич, отталкивающий противников.',
        [82953010] = 'В течении указанного времени герой выпускает больше стрел, но урон равномерно делится между стрелами на время действия. <n>Эту способность можно использовать вместе с другими атаками с использованием стрел.',
        [82953011] = 'Пущенные стрелы при попадании во врага превращаются в ядовитых пауков.',
        [82953013] = 'Стрела следует за противником и пробивает его насквозь снова и снова, пока он не умрет или пока не закончится время действия стрелы.',
        [82953124] = 'Энергетические разряды, выпускаемые с высокой частотой.',
        [82953131] = 'Вызывает волка, который помогает в бою. Этот волк наносит физический и магический урон.',
        [82953235] = 'Вызывает волка, который помогает в бою. Этот волк наносит огненный и ядовитый урон.',
        [82953236] = 'Герой совершает мгновенный рывок в указанном направлении.',
        [82953237] = 'Герой совершает мгновенный рывок в указанном направлении.',
        [82953238] = 'Парализует противника и высасывает из него жизнь на расстоянии. Снимает отравление.',
        [82953240] = 'Герой прыгает в указанное место, оглушая противников при приземлении и нанося им повреждения.',
        [82953241] = 'Герой призывает инкарнацию бога крови, которая следует за притивниками поблизости и наносит им периодические повреждения. Если противников не осталось или все противники были поражены, то инкарнация исчезает.',
        [82953242] = 'Воскрешает труп в виде вампира. Воскрешенные вампиры могут воскрешать новых вампиров.',
        [82953243] = 'Вызывает летучих мышей, которые атакуют противников и при нанесении урона восполняют здоровье героя. Эти летучие мыши наносят физический и огненный урон.',
        [82953244] = 'Вызывает летучих мышей, которые атакуют противников и могут их разоружить. Эти летучие мыши наносят магический и ядовитый урон.',
        [82953348] = 'Вызывает летучих мышей, которые получают повреждения вместо героя. Эти летучие мыши наносят физический и ядовитый урон.',
        [82953353] = 'Удар, оглушающий противника и всех врагов в радиусе от него.',
        [82953355] = 'Поглощает души убитых врагов, тем самым восполняя здоровье и снимая отравление.',
        [82953461] = 'Улучшает попадание атак и усиливает ядовитый урон.',
        [82953462] = 'Улучшает шанс избежать атак и усиливает регененрацию здоровья.',
        [82953463] = 'Герой кидает в указанное место бомбу, которая наносит повреждения всем врагам в небольшом радиусе.',
        [82953464] = 'В указанном месте с небольшой задержкой чертится символ. Наступивший на него противник получит повреждения, а символ при этом пропадет.',
        [82953465] = 'Созадет в указанном месте ловушку, которая вводит противников в замешательство и вынуждает их атаковать друг друга.',
        [82953466] = 'Создает в указанном месте облако ядовитого газа, которое наносит повреждения всем вошедшим в него врагам.',
        [82953467] = 'Создает густой туман, который парализует противников.',
        [82953808] = 'Боевая ярость увеличивает скорость атаки, а также наносимые повреждения при потере здоровья.',
        [82953809] = 'Отбрасывает и оглушает противника, нанося ему повреждения. Елси отброшенный противник задевает других врагов, то они тоже отбрасываются и оглушаются, но получают небольшие повреждения.',
        [82953913] = 'Мощный удар по противнику и находящимся рядом с ним врагам.',
        [82953915] = 'Запускает гранату в указанное место. Целью можно выбирать любые места, вне зависимости от их доступности.',
        [82953916] = 'Выстрел из пушки, наносящий повреждения указанному противнику и оглушающий его. Все враги не являющиеся основной целью, но находящиеся на траектории выстрела, также оглушаются и получают небольшие повреждения.',
        [82953918] = 'Оглушает и наносит повреждения цели и всем противникам в небольшом радиусе. Чем дальше противник от точки приземления, тем меньше он получит урона. Падение прерывает полет.',
        [82953919] = 'Серия ударов по одному противнику. Если противник умирает, а серия ударов еще не закончилась, то серия ударов продолжается на рядом стоящего противника, если такой есть.',
        [82953920] = 'Демоница некоторое время может летать, а ее защита и скорость сражения и передвижения увеличиваются. Во время действия этой формы становится доступна способность \'Падение\'.',
        [82953922] = 'Увеличивает атаку, физический урон и физическое сопротивление. Во время действия этой формы становится доступна способность \'Наступление\'.',
        [82965665] = 'Кожа героя покрывается камнем, что повышает его защиту, а также физические и ядовитые сопротивления.',
        [82965673] = 'Вызывает единорога, который будет сражаться на стороне лесной эльфийки. Единорог наносит физический и магический урон.',
        [82965674] = 'Запускает в указанном направлении огненный шар. Может поразить несколько противников, если они стоят вплотную друг к другу.',
        [82965782] = 'Герой на время становится невидимым для врагов. Невидимость прерывается при атаках и использовании способностей.',
        [82965783] = 'Восстанавливает здоровье героя и снимает отравление.',
        [82965900] = 'Наносит существенный урон противнику. Целью можно выбрать любого врага, вне зависимости от его доступности.',
        [82966125] = 'Увеличивает радиус освещения и наносит повреждения противникам.',
        [82966126] = 'Аура, существенно увеличивающая шанс попадания героя.',
        [82966232] = 'Пламя окутывает героя, защищая его от стрел и огненных повреждений, и нанося урон близко подошедшим врагам.',
        [82966234] = 'В указанное место с небольшой задержкой падают метеориты и наносят повреждения попавшим под них противникам.',
        [82966236] = 'Повышает атаку и увеличивает скорость сражения и движения.',
        [82966237] = 'Героя окружает вихрь, который наносит повреждения находящимся рядом противникам и может разоружить их, а также снижает вероятность поражения стрелками.',
        [82966349] = 'Снижает время восстановления способностей.',
        [82966350] = 'Увеличивает скорость восстановления здоровья.',
        [82966351] = 'Молния поражает противника и перескакивает на других врагов, стоящих рядом с ним.',
        [82966456] = 'Кольцо льда замедляет оппонентов и наносит им урон.',
        [82966457] = 'Превращает врагов рядом с героем в беззащитных зверей.',
        [82966458] = 'Повышает атаку и увеличивает скорость сражения и движения.',
        [82966459] = 'Запускает медленное перекати-поле, которое наносит повреждения всем противникам на пути. Если в перекати-поле попадет стрела, то она взорвется и нанесет двойные повреждения.',
        [82966460] = 'В указаном местее выростают побеги колючих растений, которые наносят противникам повреждения при контакте.',
        [82966461] = 'Опутывает противника, не давая ему двигаться.',
        [82966462] = 'Вызывает души предков, которые следуют за героем и атакуют ближайших противников.',
        [82966463] = 'Исцеляет Лесную Эльфийку и снимает эффекты отравления.',
        [82966569] = 'Увеличивает атаку и защиту героя, а также союзных героев, если они находились поблизости в момент применения способности.',
        [82966574] = 'Увеличивает атаку и снижает эффективность физических сопротивлений врага до указанного процента.',
        [82966575] = 'Создает диск, который следует за героем и атакует ближайших врагов.',
        [82966576] = 'Запускает в указанную место огненную сферу, поджигающую врагов на своем пути. По достижении указанного места сфера создает стену огня.',
        [82966577] = 'Выпускает волну яда вокруг героя, отравляющую противников поблизости.',
        [82966578] = 'НВыпускает несколько зарядов из чистой магической энергии. Разброс зарядов регулируется дальностью нажатия курсора.',
        [82966684] = 'Создает в указанном месте сферу, которая стреляет лучами в противников. Реагирует только на врагов, совершающих какие-либо действия.',
        [82966686] = 'Накладывает эффект замедления и периодического урона на находящихся рядом с героем врагов.',
        [82966688] = 'Превращает физические повреждения в повреждения огнем и увеличивает сопротивляемость огню. Во время действия этой формы становится доступна способность \'Стена пламени\'.',
        [82966689] = 'Превращает физические повреждения в повреждения ядом и увеличивает сопротивляемость ядам. Во время действия этой формы становится доступна способность \'Кольцо яда\'.',
        [82966690] = 'Превращает физические повреждения в повреждения магией и увеличивает сопротивляемость магии. Во время действия этой формы становится доступна способность \'Энергетические заряды\'.',
        [82979225] = 'Покупка рун <colorl=FFFFFF80>способностей',
        [82979227] = '<colorw=FFFFFF80>Купить <colorw=FFFFFF80>руну<n>Щелкните, чтобы купить повышение уровня способности на 1.',
        [82979230] = 'Чтобы купить повышение <colorw=FFFFFF80>уровня <colorw=FFFFFF80>способности на <colorw=FFFFFF80>1, щелкните здесь.',
        [82979231] = 'С помощью стрелок выберите <colorw=FFFFFF80>способность, уровень которой хотите повысить.<n>Чем выше <colorw=FFFFFF80>уровень <colorw=FFFFFF80>способности, тем выше <colorw=FFFFFF80>цена <colorw=FFFFFF80>покупки следующего уровня.<n><colorw=FFFFFF80>Цена <colorw=FFFFFF80>покупки показана справа. Текущий <colorw=FFFFFF80>уровень <colorw=FFFFFF80>способности показан сверху. ',
        [143359788] = 'Могила<n><n>Crackseed<n>Некий фрукт, чересчур оскорблявший одного Админа',
        [143359789] = 'Могила<n><n>\'В смысле это настоящий Гоблин?\'',
        [143359790] = 'Могила<n><n>\'Оставьте сообщение после того, как услышите вой, мы свяжемся с вами как можно скорее.\'',
        [143360579] = 'Могила<n><n>Здесь покоится А.Р.Малион. ',
        [143385782] = 'Могила<n><n>Здесь похоронена собака.',
        [143385784] = 'Могила<n><n>\'Упс!\' было его последним словом.',
        [143385891] = 'Могила<n><n>Из всего утраченного больше всего я был привязан к своему разуму.',
        [143385895] = 'Могила<n><n>Его последние слова: \'Посмотри сюда, он не кусается!\'',
        [143385900] = 'Могила<n><n>И он сказал: «А если это последнее, что я делаю!?». К сожалению, так и вышло.',
        [143386010] = 'Могила<n><n>Ему не стоило так громко кричать: \'Только через мой труп!\'',
        [143386120] = 'Могила<n><n>И ты тоже, мой сын Брут? <n>Ю. Ц.',
        [143386231] = 'Могила<n><n>В память об<n>Ральф Генрих Оберхойзер<n>* 27.02.1962<n>+ 09.11.2003<n>',
        [213026055] = 'Могила<n><n>Ваззааааап!',
        [236931057] = 'Повышает здоровье и его регенерацию, физическое сопротивление, и уменьшает восстановление особых ударов.',
        [404877779] = 'Наследие Уриэли',
        [430560712] = 'Повышает: здоровье, атаку и немного защиту, физический и огненный урон оружия и особых ударов.',
        [499408230] = 'Серафим! Вы пришли, чтобы спасти меня. Эта клетка заколдована. Чтобы разрушить ее, надо убить колдуна. ',
        [499408232] = 'Я спасена! Не беспокойтесь больше обо мне, сестра по оружию. Мы избавились от тюрьмы, созданной колдуном, и теперь я смогу выбраться на свободу. <n>Я расскажу об этой секте Вестону, который служит под началом командира Роматы. <n>И еще кое-что: я слышала, как колдун бормотал что-то о \'серебристой крови серафима\'. Не держат ли сектанты в плену одну из ваших кровных сестер? ',
        [583350231] = 'Вы пережили предательство ДеМордри  Проводите меня в Тир-Фасул, там мы найдем принца Валора! <n><n>Да, он рассказал мне о вас перед битвой в ущелье виверн. Он еще жив, хотя ходят слухи, что он пал в бою, когда барон ДеМордри предал его... <n>Мой возлюбленный принц ушел с поля боя с горсткой преданных ему людей и бежал сюда. Он добрался до заброшенной крепости в лесах Тир-Фасула, где он и его люди остановились, чтобы излечить свои раны. Вскоре после этого ДеМордри занял мои земли и запер меня в моем собственном доме.<n>Влияние ДеМордри растет с каждым днем! Он претендует на трон умирающего Аарнума! <n>Проведите меня мимо его людей… отведите меня к принцу. Но, прежде всего, мне нужно дорожное платье, чтобы отправится в путь.',
        [594737219] = 'Повышает: защиту и немного атаку, физический урон в дальнем бою, сопротивление огню и огненный урон оружия и особых ударов.',
        [596956729] = 'Позволяет телепортироваться к одному из городских порталов.',
        [604473972] = 'Аньянка Спелл',
        [704609630] = 'Я спасена! Не беспокойтесь больше обо мне, мы избавились от тюрьмы, созданной колдуном, и теперь я смогу выбраться на свободу. <n>Я расскажу об этой секте Вестону, который служит под началом командира Роматы. <n>И еще кое-что: я слышала, как колдун бормотал что-то о \'серебристой крови серафима\'. Может быть, серафим содержится где-то у них в плену? ',
        [743050080] = 'Исцеляет от отравления ядом',
        [772943506] = 'Могила<n><n> И Торвин сказал:\'Если вы так и будете бездельничать, я пойду вперед!\'',
