        [772955706] = 'Статуя<n><n>Гаргулья',
        [946147370] = 'Капитан рассказал мне о трех группах ледяных эльфов, каждую из которых возглавляет жрица. Чтобы восстановить мир, мне нужно убить всех трех жриц. Ворота теперь открыты, так что я могу использовать их для того, чтобы сокращать путь. Если я не успею убить ледяных эльфов вовремя, они нападут на лагерь лесных эльфов.',
        [946147371] = 'Первая жрица мертва. Теперь нужно найти остальных двух.',
        [946147372] = 'Дело почти сделано. Чтобы освободить степи, осталось лишь убить последнюю жрицу.',
        [946147373] = 'Все жрицы мертвы. Задание выполнено. Теперь нужно поговорить с предводителем эльфов в лагере.',
